import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => createHost();

test('initial state', async () => {
  const h = await fresh();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.equal(await h.order('x'), null);
  assert.deepEqual(await h.inFlight(), []);
  assert.equal((await h.cancel('x')).ok, false);
  await h.__dispose();
});

test('place and confirm', async () => {
  const h = await fresh();
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
  await h.deliver(msgs[0].id);
  const [reply] = await h.inFlight();
  assert.deepEqual({ from: reply.from, to: reply.to, action: reply.action, data: reply.data }, { from: 'inventory', to: 'a', action: 'Reserved', data: {} });
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  const [rel] = await h.inFlight();
  assert.deepEqual({ action: rel.action, data: rel.data }, { action: 'Release', data: { qty: 1 } });
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.__dispose();
});

test('bad qty and rejection', async () => {
  const h = await fresh();
  assert.equal((await h.place('a', 3)).ok, false);
  assert.equal((await h.place('a', 0)).ok, false);
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.place('a', 2), { ok: true });
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'rejected', qty: 2 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  await h.__dispose();
});

test('cancel while pending', async () => {
  const h = await fresh();
  await h.place('a', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'cancelling', qty: 1 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  await h.place('b', 2);
  await h.cancel('b');
  await h.deliverAll();
  assert.deepEqual(await h.order('b'), { status: 'cancelled', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  await h.__dispose();
});

test('restock bound', async () => {
  const h = await fresh();
  assert.deepEqual(await h.restock(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  assert.equal((await h.restock()).ok, false);
  await h.place('a', 2);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 2 });
  assert.equal((await h.restock()).ok, false);
  await h.__dispose();
});

